updated_count = 0
not_found = []

for ticker, description in descriptions.items():
    updated = Company.objects.filter(ticker=ticker).update(
        description=description
    )

    if updated:
        updated_count += updated
        print(f"✓ {ticker}")
    else:
        not_found.append(ticker)
        print(f"✗ {ticker} — не найден")


print()
print(f"Обновлено компаний: {updated_count}")
print(f"Не найдено: {len(not_found)}")

